-- ── hand-written: a posted journal is never changed or removed ──────────────────────────────────
-- Refuses every UPDATE, DELETE and TRUNCATE on the ledger, whoever asks, the table's owner
-- included. A wrong journal is corrected by a reversal, which is a new journal.
--
-- The one exception is removing a whole company, which the app can never do: a session signed
-- in as postgres itself (not the app, not the worker) may delete the rows of the companies it
-- has named in the setting app.purge_tenants (ids separated by commas) for that transaction.
-- The tests use it to remove the synthetic companies they create. The triggers are ENABLE
-- ALWAYS, so a session in replica mode does not skip them.
CREATE FUNCTION app.refuse_ledger_change() RETURNS trigger
  LANGUAGE plpgsql SET search_path = ''
  AS $$
BEGIN
  IF TG_OP = 'DELETE'
     AND session_user = 'postgres'
     AND OLD.tenant_id::text = ANY (string_to_array(coalesce(current_setting('app.purge_tenants', true), ''), ','))
  THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'a posted journal is never changed or removed; post a reversal instead' USING ERRCODE = 'SE020';
END $$;
--> statement-breakpoint
