-- ── hand-written: what a journal line may be ────────────────────────────────────────────────────
-- A line joins its journal only in the transaction that wrote the journal: nothing is added to
-- a journal afterwards. It names an account that is not a heading and, unless the journal is a
-- reversal, not archived. A line on trade receivables or advances from customers names its
-- customer, and a line on trade payables or advances to suppliers its supplier, so each of those
-- accounts always equals the sum of its parties. The line takes the journal's branch.
CREATE FUNCTION app.check_journal_line() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_journal public.journals%ROWTYPE;
  v_account public.accounts%ROWTYPE;
BEGIN
  SELECT j.* INTO v_journal FROM public.journals j WHERE j.tenant_id = NEW.tenant_id AND j.id = NEW.journal_id;
  IF NOT FOUND THEN
    -- Left for the foreign key to refuse.
    RETURN NEW;
  END IF;
  IF v_journal.posted_txid <> txid_current() OR v_journal.created_at <> transaction_timestamp() THEN
    RAISE EXCEPTION 'a posted journal is never changed; post a reversal instead' USING ERRCODE = 'SE020';
  END IF;
  SELECT a.* INTO v_account FROM public.accounts a WHERE a.tenant_id = NEW.tenant_id AND a.id = NEW.account_id;
  IF NOT FOUND THEN
    RETURN NEW;
  END IF;
  IF v_account.is_group THEN
    RAISE EXCEPTION 'account % is a heading; amounts go to the accounts under it', v_account.code USING ERRCODE = 'SE011';
  END IF;
  IF v_account.archived_at IS NOT NULL AND v_journal.reverses_journal_id IS NULL THEN
    RAISE EXCEPTION 'account % is archived', v_account.code USING ERRCODE = 'SE012';
  END IF;
  IF v_account.control_type IN ('ar', 'customer_advances') AND NEW.customer_id IS NULL THEN
    RAISE EXCEPTION 'a line on account % names its customer', v_account.code USING ERRCODE = 'SE013';
  END IF;
  IF v_account.control_type IN ('ap', 'supplier_advances') AND NEW.supplier_id IS NULL THEN
    RAISE EXCEPTION 'a line on account % names its supplier', v_account.code USING ERRCODE = 'SE014';
  END IF;
  NEW.branch_id := v_journal.branch_id;
  RETURN NEW;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_journal_line() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER journal_lines_check
  BEFORE INSERT ON public.journal_lines
  FOR EACH ROW EXECUTE FUNCTION app.check_journal_line();
--> statement-breakpoint
ALTER TABLE public.journal_lines ENABLE ALWAYS TRIGGER journal_lines_check;
--> statement-breakpoint

-- ── hand-written: a journal balances ────────────────────────────────────────────────────────────
-- Checked when the transaction commits, for every line written and for every journal written:
-- a journal has at least two lines and its debits equal its credits, or nothing of the
-- transaction is kept. This holds whoever writes the rows.
CREATE FUNCTION app.check_journal_balanced() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_journal uuid;
  v_lines integer;
  v_debit numeric;
  v_credit numeric;
BEGIN
  IF TG_TABLE_NAME = 'journals' THEN
    v_journal := NEW.id;
  ELSE
    v_journal := NEW.journal_id;
  END IF;
  SELECT count(*), coalesce(sum(l.debit), 0), coalesce(sum(l.credit), 0) INTO v_lines, v_debit, v_credit
    FROM public.journal_lines l WHERE l.tenant_id = NEW.tenant_id AND l.journal_id = v_journal;
  IF v_lines < 2 THEN
    RAISE EXCEPTION 'a journal has at least two lines' USING ERRCODE = 'SE003';
  END IF;
  -- "Not a number" equals itself, so it is named: no sum of real amounts is ever that.
  IF v_debit IS DISTINCT FROM v_credit OR v_debit = 'NaN'::numeric THEN
    RAISE EXCEPTION 'the journal does not balance: debits %, credits %', v_debit, v_credit USING ERRCODE = 'SE003';
  END IF;
  RETURN NULL;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_journal_balanced() FROM PUBLIC;
--> statement-breakpoint
CREATE CONSTRAINT TRIGGER journal_lines_balanced
  AFTER INSERT ON public.journal_lines
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION app.check_journal_balanced();
--> statement-breakpoint
ALTER TABLE public.journal_lines ENABLE ALWAYS TRIGGER journal_lines_balanced;
--> statement-breakpoint
CREATE CONSTRAINT TRIGGER journals_balanced
